def first_group(apps, schema_editor):
    """The platform's first group is the one this installation was built
    for, named from its settings."""
    Group = apps.get_model("core", "Group")
    Settings = apps.get_model("core", "Settings")
    st = Settings.objects.order_by("pk").first()
    name = (st.name if st else "") or "Mouvement Garde Suisse"
    Group.objects.get_or_create(slug=slugify(name)[:50] or "groupe", defaults={"name": name})


def memberships(apps, schema_editor):
    """Everyone already here belongs to the first group — except super
    admins, who run the platform rather than belong to a group."""
    Group = apps.get_model("core", "Group")
    Membership = apps.get_model("core", "Membership")
    User = apps.get_model("accounts", "User")
    RoleAssignment = apps.get_model("accounts", "RoleAssignment")
    group = Group.objects.order_by("pk").first()
    admins = set(RoleAssignment.objects.filter(role__slug="super-admin", revoked_at__isnull=True).values_list("user_id", flat=True))
    Membership.objects.bulk_create(
        [Membership(user=u, group=group, joined_on=u.joined_on) for u in User.objects.exclude(pk__in=admins)],
        ignore_conflicts=True,
    )


